<?php
declare(strict_types=1);
header('Content-Type: application/json; charset=utf-8');
header('Cache-Control: no-store');
$expected='__TOKEN__';
if(!hash_equals($expected,(string)($_SERVER['HTTP_X_TASK_TOKEN']??''))){http_response_code(403);exit;}
@unlink(__FILE__);
try{
  $c=require __DIR__.'/config.php';
  $pdo=new PDO('mysql:host='.$c['db_host'].';dbname='.$c['db_name'].';charset=utf8mb4',$c['db_user'],$c['db_pass'],[
    PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,
    PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,
  ]);
  $allowed=['میوه و سبزی','لبنیات و صبحانه','نوشیدنی','تنقلات و شیرینی','خانه و شوینده','گوشت و مرغ','مواد غذایی','کنسرو و غذای آماده','بهداشت شخصی','کودک','دخانیات','سایر'];
  function nrm(string $s): string {
    $s=strtr($s,['ي'=>'ی','ى'=>'ی','ك'=>'ک','ة'=>'ه','ۀ'=>'ه','ؤ'=>'و','إ'=>'ا','أ'=>'ا','آ'=>'ا','‌'=>' ']);
    $s=mb_strtolower($s,'UTF-8');
    $s=preg_replace('/[\x{064B}-\x{065F}\x{0670}]/u','',$s)??$s;
    $s=preg_replace('/[^0-9a-zآ-ی]+/u',' ',$s)??$s;
    return trim(preg_replace('/\s+/u',' ',$s)??$s);
  }
  function hit(string $t,array $words): bool {
    foreach($words as $w){if($w!=='' && mb_strpos($t,$w,0,'UTF-8')!==false)return true;}
    return false;
  }
  function classify(string $text,string $current): string {
    $t=nrm($text);
    // Age-restricted / smoking accessories first, so charcoal and lighters do not fall into household.
    if(hit($t,['سیگار','سیگارت','تنباکو','توتون','قلیان','ذغال','زغال','فندک','کبریت','پیپ','ویپ','ویپینگ','پاد','پادماد','جویس','ایجویس','فیلتر سیگار','کاغذ سیگار','کاغذ پیچ','نسوار'])) return 'دخانیات';
    if(hit($t,['پوشک بچه','پوشک کودک','شیر خشک','غذای کودک','غذای نوزاد','سرلاک','پستانک','شیشه شیر','دندانگیر','دستمال مرطوب کودک','دستمال مرطوب بچه','بچه گانه','نوزاد','کودک'])) return 'کودک';
    if(hit($t,['شامپو','نرم کننده مو','ماسک مو','رنگ مو','صابون','مایع دستشویی','خمیر دندان','مسواک','دهانشویه','نخ دندان','تیغ','ژیلت','افترشیو','مام','دئودورانت','اسپری بدن','عطر','ادکلن','کرم دست','کرم صورت','کرم بدن','لوسیون','وازلین','ضد آفتاب','نوار بهداشتی','پد بهداشتی','پنبه','گوش پاک کن','دستمال کاغذی جیبی','کاندوم'])) return 'بهداشت شخصی';
    if(hit($t,['مایع ظرفشویی','قرص ماشین ظرفشویی','نمک ماشین ظرفشویی','جلادهنده','مایع لباسشویی','پودر لباسشویی','پودر دستی','پودر ماشین','نرم کننده لباس','مایع سفیدکننده','سفید کننده','وایتکس','جرم گیر','چربی گیر','شیشه پاک کن','پاک کننده سطوح','پاک کننده','ضدعفونی کننده','اسکاچ','ابر ظرفشویی','سیم ظرفشویی','دستکش ظرفشویی','کیسه زباله','کیسه فریزر','فویل آلومینیوم','سلفون','دستمال حوله ای','دستمال آشپزخانه','دستمال توالت','حشره کش','بوگیر','خوشبو کننده هوا','تی','جارو','شمع','لامپ','باتری'])) return 'خانه و شوینده';
    if(hit($t,['گوشت','مرغ','جوجه','ماهی','میگو','سوسیس','کالباس','همبرگر','برگر','هات داگ','ژامبون','فیله مرغ','ران مرغ','سینه مرغ','دل مرغ','جگر','قلوه','گوشت چرخ کرده','گوشت گوسفند','گوشت گوساله'])) return 'گوشت و مرغ';
    if(hit($t,['شیر','ماست','دوغ','پنیر','کره','خامه','کشک','بستنی','تخم مرغ','مربا','عسل','ارده','حلوا شکری','حلواشکری','شکلات صبحانه','کره بادام زمینی','کورن فلکس','غلات صبحانه','گرانولا','پنیرک','پنیر خامه ای'])) return 'لبنیات و صبحانه';
    if(hit($t,['نوشابه','آب معدنی','آب آشامیدنی','آبمیوه','آب میوه','نکتار','دلستر','ماءالشعیر','انرژی زا','انرژی‌زا','شربت','چای','قهوه','نسکافه','کاپوچینو','هات چاکلت','پودر کاکائو نوشیدنی','دوغ گازدار'])) return 'نوشیدنی';
    if(hit($t,['چیپس','پفک','اسنک','پاپ کورن','پاپکورن','بیسکویت','ویفر','کلوچه','کیک','شکلات','آبنبات','آدامس','پاستیل','تافی','کوکی','کراکر','لواشک','ترشک','آجیل','خشکبار','بادام','پسته','فندق','گردو','تخمه','کشمش','نخودچی','خرما شکلاتی'])) return 'تنقلات و شیرینی';
    if(hit($t,['کنسرو','کمپوت','تن ماهی','تن ماهی','کنسرو لوبیا','کنسرو عدسی','کنسرو نخود','کنسرو ذرت','کنسرو قارچ','نودل','سوپ آماده','غذای آماده','خوراک آماده','آش آماده','کشک بادمجان آماده','الویه','سالاد آماده','ساندویچ آماده','فلافل آماده','سمبوسه'])) return 'کنسرو و غذای آماده';
    if(hit($t,['سیب','پرتقال','نارنگی','موز','کیوی','خیار','گوجه','گوجه فرنگی','پیاز','سیب زمینی','هویج','کاهو','کلم','سبزی','ریحان','جعفری','گشنیز','شوید','نعنا','فلفل دلمه','بادمجان','کدو','قارچ تازه','لیمو','لیمو ترش','هندوانه','طالبی','خربزه','انگور','هلو','شلیل','زردآلو','آلو','انار','توت فرنگی','میوه','سبزیجات'])) return 'میوه و سبزی';
    if(hit($t,['برنج','ماکارونی','پاستا','رشته','عدس','لوبیا','نخود','لپه','جو','بلغور','گندم','آرد','نشاسته','شکر','قند','نمک','ادویه','فلفل سیاه','زردچوبه','دارچین','زعفران','روغن','رب گوجه','سس','مایونز','کچاپ','سرکه','آبلیمو','آبغوره','خیارشور','ترشی','زیتون','پودر سوخاری','پودر کیک','پودر ژله','ژله','پودر دسر','وانیل','بکینگ پودر','خمیرمایه','سویا','بلغور','جو پرک'])) return 'مواد غذایی';
    $cur=trim($current);
    if(in_array($cur,['میوه و سبزی','لبنیات و صبحانه','نوشیدنی','تنقلات و شیرینی','خانه و شوینده','گوشت و مرغ','مواد غذایی','کنسرو و غذای آماده','بهداشت شخصی','کودک','دخانیات'],true)) return $cur;
    return 'سایر';
  }
  $rows=$pdo->query("SELECT id,name,brand,quantity_label,category FROM products WHERE active=1 ORDER BY id")->fetchAll();
  $upd=$pdo->prepare('UPDATE products SET category=?,updated_at=NOW() WHERE id=? AND category<>?');
  $counts=array_fill_keys($allowed,0);$changed=0;
  $pdo->beginTransaction();
  foreach($rows as $r){
    $text=implode(' ',[(string)($r['name']??''),(string)($r['brand']??''),(string)($r['quantity_label']??''),(string)($r['category']??'')]);
    $cat=classify($text,(string)($r['category']??''));
    if(!isset($counts[$cat]))$cat='سایر';
    $counts[$cat]++;
    if((string)($r['category']??'')!==$cat){$upd->execute([$cat,(int)$r['id'],$cat]);$changed+=$upd->rowCount();}
  }
  $pdo->commit();
  ksort($counts,SORT_STRING);
  echo json_encode(['ok'=>true,'total'=>count($rows),'changed'=>$changed,'counts'=>$counts],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
}catch(Throwable $e){if(isset($pdo)&&$pdo instanceof PDO&&$pdo->inTransaction())$pdo->rollBack();http_response_code(500);echo json_encode(['ok'=>false,'error'=>'CAT-500'],JSON_UNESCAPED_UNICODE);}
